const e=[{id:"stat-edition",value:"04",label:"Edition",isPlaceholder:!1,subtext:"Fourth Flagship Edition"},{id:"stat-mode",value:"Online",label:"Conference Format",isPlaceholder:!1,subtext:"Convened Digitally Worldwide"},{id:"stat-committees",value:"04",label:"Flagship Simulation Councils",isPlaceholder:!1,subtext:"UNSC, UNHRC, UNCSW & AIPPM"},{id:"stat-delegates",value:"Open",label:"Participation Cohort",isPlaceholder:!1,subtext:"Students & Working Professionals"}],i={overview:"NITAMUN 4.0 is the flagship online Model United Nations conference organised by the Model United Nations Society (MUNSOC) of the National Institute of Technology Agartala. Convened entirely online, NITAMUN 4.0 provides a premier international platform bringing together students and working professionals to experience diplomacy, debate, and international relations at the highest substantive standard.",munsocNarrative:"Founded as an intellectual crucible within NIT Agartala, MUNSOC has fostered a community of debaters, policy analysts, and multilateral thinkers. The society organises year-round parliamentary workshops, training caucuses, and crisis simulations, bringing together collegiate scholars, school debaters, and working professionals from across the globe.",vision:"To cultivate an empowered generation of empathetic, analytically rigorous leaders who approach global friction not through polarizing rhetoric, but through constructive negotiation, legal precision, and multilateral statecraft.",mission:"To provide an uncompromising online simulation environment where participants experience the immense responsibility of foreign policy formulation, master the United Nations Rules of Procedure, and draft actionable solutions to the century's most pressing global crises.",objectives:[{number:"01",title:"Geopolitical Rigour",description:"Ensuring online committee simulations adhere strictly to authentic United Nations charters, precedent treaties, and verified diplomatic protocols."},{number:"02",title:"Intellectual Sovereignty",description:"Challenging delegates to inhabit unfamiliar sovereign worldviews, setting aside personal convictions to represent national interests authentically."},{number:"03",title:"Pragmatic Consensus",description:"Guiding the transition of impassioned floor speeches into actionable, clause-by-clause draft resolutions and binding multilateral agreements."},{number:"04",title:"Inclusive Access",description:"Connecting scholars, students, and working professionals across diverse geographic regions through an accessible, high-caliber virtual forum."}],whyParticipate:[{id:"why-1",title:"Executive Board Excellence",category:"Substantive Quality",description:"Our committees are adjudicated by seasoned Executive Board members with deep circuit experience and rigorous procedural expertise.",iconName:"Scale"},{id:"why-2",title:"Diverse Delegate Cohort",category:"Global Network",description:"Engage with students and working professionals from diverse academic disciplines and industries worldwide.",iconName:"Globe"},{id:"why-3",title:"Prestige & Recognition",category:"Awards & CV",description:"Official certificates of statesmanship and merit awards: Best Delegate, High Commendation, Special Mention, and Verbal Mentions.",iconName:"Award"},{id:"why-4",title:"Multilateral Statecraft",category:"Diplomatic Skills",description:"Master unmoderated caucus lobbying, cross-table bloc formation, and the fine art of diplomatic compromise in virtual chambers.",iconName:"Briefcase"},{id:"why-5",title:"Seamless Digital Experience",category:"Online Infrastructure",description:"Curated virtual committee rooms, real-time crisis bulletins, and structured digital resolution drafting sessions.",iconName:"Users"}]},t=[{id:"unsc",acronym:"UNSC",name:"United Nations Security Council",type:"Continuous Crisis / Specialized Agency",delegationType:"Single Delegate (P5 & Elected Members)",agenda:{status:"TBA",title:"[AGENDA PLACEHOLDER: ADDRESSING ESCALATING MARITIME SECURITY DISPUTES AND NON-STATE ACTORS IN STRATEGIC STRAITS]",description:"Official agenda text to be released by the Executive Board alongside the background guide."},overview:"The pre-eminent organ tasked with the maintenance of international peace and security under the UN Charter. Featuring legally binding resolutions, presidential statements, and rapid, high-stakes continuous crisis updates that test tactical statecraft under immense pressure.",mandate:"Charter of the United Nations (Chapter VI & VII Enforcement Powers), UN Peacekeeping Directives.",expectedOutcomes:["Binding UN Security Council Resolutions","Presidential Statements","Emergency Crisis Directives"],backgroundGuideStatus:"Coming Soon"},{id:"unhrc",acronym:"UNHRC",name:"United Nations Human Rights Council",type:"Conventional General Assembly Body",delegationType:"Single Delegate",agenda:{status:"TBA",title:"[AGENDA PLACEHOLDER: SAFEGUARDING CIVIL LIBERTIES AND COMBATING SYSTEMIC SURVEILLANCE ASYMMETRY IN DIGITAL AUTHORITARIAN STATES]",description:"Official agenda item examining systemic humanitarian violations, privacy protections, and universal rights frameworks."},overview:"Responsible for strengthening the promotion and protection of human rights globally. Delegates tackle urgent humanitarian imperatives, examining state accountability, refugee protections, civil liberties, and institutional equity across jurisdictions.",mandate:"Universal Declaration of Human Rights (UDHR), International Covenant on Civil and Political Rights (ICCPR).",expectedOutcomes:["Universal Periodic Review Recommendations","Human Rights Draft Resolutions","Fact-Finding Directives"],backgroundGuideStatus:"Coming Soon"},{id:"uncsw",acronym:"UNCSW",name:"United Nations Commission on the Status of Women",type:"Functional Commission of ECOSOC",delegationType:"Single Delegate",agenda:{status:"TBA",title:"[AGENDA PLACEHOLDER: ACCELERATING GENDER EQUALITY AND ECONOMIC SOVEREIGNTY IN POST-CRISIS POST-CONFLICT RECONSTRUCTION]",description:"Official agenda focusing on socioeconomic empowerment, structural protections, and institutional legislative parity."},overview:"The principal global intergovernmental body dedicated exclusively to the promotion of gender equality and the empowerment of women. Delegates debate socio-economic barriers, institutional equity, maternal health protections, and legislative parity across emerging economies.",mandate:"Beijing Declaration and Platform for Action, CEDAW Convention, Sustainable Development Goal 5.",expectedOutcomes:["Agreed Conclusions (AC)","Action Plans for Legislative Parity","Regional Policy Directives"],backgroundGuideStatus:"Coming Soon"},{id:"aippm",acronym:"AIPPM",name:"All India Political Parties Meet",type:"Specialized Indian Parliamentary Simulation",delegationType:"Single Representative (Indian Political Leaders)",agenda:{status:"TBA",title:"[AGENDA PLACEHOLDER: COMPREHENSIVE REVIEW OF FISCAL FEDERALISM, ELECTORAL MECHANISMS, AND INTER-STATE RESOURCE ALLOCATIONS]",description:"Official agenda mirroring pressing national legislative, constitutional, and economic debates."},overview:"A high-octane parliamentary forum capturing the vibrancy, ideological friction, and constitutional debates of Indian politics. Representatives articulate political party lines, cross-examine national policies, and negotiate bipartisan legislative consensus.",mandate:"Constitution of India, Parliamentary Conventions, Lok Sabha & Rajya Sabha Rules of Procedure.",expectedOutcomes:["Joint Parliamentary Communiqué","Private Member Recommendations","National Policy Revisions"],backgroundGuideStatus:"Coming Soon"}],a=[{id:"sec-sg",name:"[NAME PLACEHOLDER — EDITABLE]",role:"Secretary-General",department:"Executive Secretariat",message:"Welcoming delegates to an intellectually demanding online edition dedicated to genuine diplomatic empathy and rigor.",isPlaceholder:!0},{id:"sec-dsg",name:"[NAME PLACEHOLDER — EDITABLE]",role:"Deputy Secretary-General",department:"Executive Secretariat",message:"Guiding institutional coherence, academic consistency, and delegate care across all four councils.",isPlaceholder:!0},{id:"sec-dg",name:"[NAME PLACEHOLDER — EDITABLE]",role:"Director-General",department:"Operations & Digital Infrastructure",message:"Ensuring an effortless virtual conference infrastructure from inaugural plenary to the closing gavel strike.",isPlaceholder:!0},{id:"sec-cd",name:"[NAME PLACEHOLDER — EDITABLE]",role:"Charge d'Affaires",department:"Institutional Relations",message:"Fostering partnerships with educational institutions, professional networks, and international diplomatic societies.",isPlaceholder:!0},{id:"sec-usg-sub",name:"[NAME PLACEHOLDER — EDITABLE]",role:"USG Substantive Affairs",department:"Substantive Board",message:"Crafting authoritative background dossiers, procedural guidelines, and continuous crisis architectures.",isPlaceholder:!0},{id:"sec-usg-del",name:"[NAME PLACEHOLDER — EDITABLE]",role:"USG Delegate Affairs",department:"Delegate Experience",message:"Your primary point of contact for portfolio allocations, queries, and virtual room orientations.",isPlaceholder:!0}],n=[{step:"01",title:"Research & Synthesis",subtitle:"The Foundation of Sovereign Stance",description:"Diplomacy does not begin at the podium; it begins in deep archival inquiry. Delegates interrogate treaties, UN resolutions, economic pacts, and cultural nuances to construct an unshakeable policy stance.",diplomaticFocus:"Treaty analysis, country dossiers, and bilateral history mapping.",quote:"To speak for a nation, one must first master its deepest anxieties and highest aspirations.",iconName:"Search"},{step:"02",title:"Representation & Decorum",subtitle:"The Embodiment of Statecraft",description:"Stepping beyond personal bias, every delegate embodies the diplomatic poise, legal obligations, and strategic leverage of their assigned portfolio with uncompromising procedural precision.",diplomaticFocus:"Rules of Procedure (RoP), diplomatic decorum, and formal address.",quote:"A diplomat does not express opinion; a diplomat articulates sovereign will.",iconName:"UserCheck"},{step:"03",title:"Debate & Interpellation",subtitle:"The Crucible of Ideas",description:"General Speakers Lists, Moderated Caucuses, and Point of Information interpellations test rhetorical clarity and intellectual agility under the relentless scrutiny of the Executive Board.",diplomaticFocus:"Persuasive oratory, crisis response, and multilateral discourse.",quote:"In the chamber of nations, the strongest argument is forged in restraint and facts.",iconName:"Mic"},{step:"04",title:"Negotiation & Bloc Alliances",subtitle:"The Art of the Unmoderated Caucus",description:"Beyond the formal dais, the chamber dissolves into strategic coalitions. Blocs form, regional interests align, and diplomatic compromises are negotiated through bilateral statecraft.",diplomaticFocus:"Bilateral pacts, caucus lobbying, and strategic concessions.",quote:"Agreements are drafted in ink, but negotiated through trust and leverage.",iconName:"Handshake"},{step:"05",title:"Resolution & Consensus",subtitle:"The Sovereign Document",description:"The culmination of hours of exhaustive committee work: authoring operative clauses, surviving line-by-line amendments, and navigating decisive roll-call votes to seal the conference declaration.",diplomaticFocus:"Working papers, draft resolutions, amendment ballots, and press communiqués.",quote:"A resolution is not a victory of one; it is a shared triumph of compromise.",iconName:"FileCheck"}],o=[{id:"faq-01",question:"What is NITAMUN 4.0?",answer:"NITAMUN 4.0 is the fourth edition of the flagship Model United Nations conference organised by MUNSOC, the Model United Nations Society of the National Institute of Technology Agartala. It simulates high-level international multilateral bodies and parliamentary forums in an online format, offering delegates a premier platform to practice diplomacy, debate pressing global dilemmas, and draft actionable resolutions.",category:"General"},{id:"faq-02",question:"What is the mode and dates of the conference?",answer:"NITAMUN 4.0 is conducted entirely online on January 23–24, 2027. Participants can join the virtual committee chambers remotely from anywhere in India or internationally.",category:"Format"},{id:"faq-03",question:"Who is eligible to participate in NITAMUN 4.0?",answer:"Participation is open to school scholars, undergraduate students, postgraduate scholars, and working professionals. Anyone with an interest in international relations, public policy, or debate is warmly encouraged to apply.",category:"Participation"},{id:"faq-04",question:"What are the registration fees and deadlines?",answer:"Registration is for individual delegates with tiered fees: Early Bird is ₹400 (till Nov 30), Regular is ₹450 (till Jan 10), and Late is ₹500 (after Jan 10). The official registration link will be published soon by the Secretariat.",category:"Participation"},{id:"faq-05",question:"What awards are conferred per committee?",answer:"Each of the four simulation committees confers: Best Delegate (1), High Commendation (1), Special Mention (1), and Verbal/Honorable Mentions (5), accompanied by official digital certificates of statesmanship.",category:"Committees"},{id:"faq-06",question:"Do I need prior Model UN experience?",answer:"No prior MUN experience is required. While seasoned debaters will appreciate our substantive scrutiny, first-time participants will receive comprehensive Background Guides, Rules of Procedure (RoP) manuals, and orientation before committee sessions commence.",category:"General"}];export{i as a,a as b,t as c,n as e,o as f,e as s};
